('1','6b98da98-7378-4921-82be-dc009e62c41f','sample_training_data.json','mixed','10','9','1','completed','[{\"item\": {\"tags\": [\"enrollment\", \"schedule\", \"registrar\", \"dates\"], \"type\": \"conversation\", \"context\": \"general\", \"category\": \"academic\", \"priority\": \"high\", \"user_message\": \"When is the enrollment period?\", \"assistant_response\": \"The enrollment period typically runs from [specific dates]. For the most current enrollment schedule, please check the official announcements in StudentLink or contact the Registrar\'s Office. You can also submit a concern to get specific enrollment information.\"}, \"error\": \"SQLSTATE[22001]: String data, right truncated: 1406 Data too long for column \'assistant_response\' at row 1 (Connection: mysql, SQL: insert into `training_data` (`type`, `user_message`, `assistant_response`, `category`, `context`, `tags`, `priority`, `active`, `source`, `batch_id`, `created_by`, `updated_at`, `created_at`) values (conversation, When is the enrollment period?, The enrollment period typically runs from [specific dates]. For the most current enrollment schedule, please check the official announcements in StudentLink or contact the Registrar\'s Office. You can also submit a concern to get specific enrollment information., academic, general, [\\\"enrollment\\\",\\\"schedule\\\",\\\"registrar\\\",\\\"dates\\\"], 3, 1, bulk_import, 6b98da98-7378-4921-82be-dc009e62c41f, 40, 2025-09-16 18:55:00, 2025-09-16 18:55:00))\", \"index\": 4}]','40','2025-09-16 18:55:00','2025-09-16 18:55:00','2025-09-16 18:55:00'),
