INSERT INTO `training_data` VALUES
('1','faq','How do I submit a concern?','You can submit a concern by going to the \'Submit Concern\' section in the mobile app or web portal. Fill out the form with your details, select the appropriate department, and describe your concern. You\'ll receive a reference number to track your concern\'s progress.',NULL,NULL,NULL,NULL,NULL,'concern','general','[\"concern\", \"submit\", \"help\", \"form\"]','3','1','bulk_import','6b98da98-7378-4921-82be-dc009e62c41f','40','2025-09-16 18:55:00','2025-09-16 18:55:00'),
('2','faq','What are the emergency contacts?','For emergencies, you can contact:\n- Campus Security: (02) 123-4567\n- Medical Center: (02) 123-4568\n- Fire Department: 911\n- Police: 911\n\nFor non-emergency concerns, use the StudentLink app to submit a concern.',NULL,NULL,NULL,NULL,NULL,'emergency','general','[\"emergency\", \"contacts\", \"security\", \"medical\"]','4','1','bulk_import','6b98da98-7378-4921-82be-dc009e62c41f','40','2025-09-16 18:55:00','2025-09-16 18:55:00'),
('3','faq','How do I reset my password?','To reset your password:\n1. Go to the login page\n2. Click \'Forgot Password\'\n3. Enter your email address\n4. Check your email for reset instructions\n5. Follow the link to create a new password\n\nIf you need help, contact the IT department through StudentLink.',NULL,NULL,NULL,NULL,NULL,'technical','general','[\"password\", \"reset\", \"login\", \"account\"]','3','1','bulk_import','6b98da98-7378-4921-82be-dc009e62c41f','40','2025-09-16 18:55:00','2025-09-16 18:55:00'),
('4','conversation',NULL,NULL,'I need help with my grades','I can help you with grade-related questions. You can check your grades in the student portal or contact your instructor directly. If you have concerns about a specific grade, you can submit a concern through StudentLink to the Academic Affairs department.',NULL,NULL,NULL,'academic','general','[\"grades\", \"academic\", \"help\", \"portal\"]','2','1','bulk_import','6b98da98-7378-4921-82be-dc009e62c41f','40','2025-09-16 18:55:00','2025-09-16 18:55:00'),
('5','department_info',NULL,NULL,NULL,NULL,'Registrar Office','Grade Change Request','Grade change requests must be submitted within 30 days of grade posting. Contact the Registrar Office for the proper form and requirements. The process includes instructor approval and department head review.','academic','general','[\"grades\", \"registrar\", \"forms\", \"change\"]','3','1','bulk_import','6b98da98-7378-4921-82be-dc009e62c41f','40','2025-09-16 18:55:00','2025-09-16 18:55:00'),
('6','department_info',NULL,NULL,NULL,NULL,'IT Department','System Access Issues','If you\'re experiencing system access issues, try clearing your browser cache first. For persistent problems, contact the IT Department through StudentLink. Common issues include login problems, portal access, and email connectivity.','technical','general','[\"it\", \"access\", \"login\", \"portal\", \"email\"]','2','1','bulk_import','6b98da98-7378-4921-82be-dc009e62c41f','40','2025-09-16 18:55:00','2025-09-16 18:55:00'),
('7','department_info',NULL,NULL,NULL,NULL,'Library','Library Services','The library is open Monday-Friday 8AM-8PM, Saturday 9AM-5PM. Services include book borrowing, research assistance, computer access, and study spaces. You can reserve study rooms through the library website or in person.','services','general','[\"library\", \"hours\", \"books\", \"study\", \"research\"]','2','1','bulk_import','6b98da98-7378-4921-82be-dc009e62c41f','40','2025-09-16 18:55:00','2025-09-16 18:55:00'),
('8','faq','How do I contact my instructor?','You can contact your instructor through:\n1. Email (check your course syllabus)\n2. Office hours (posted on their door or course materials)\n3. StudentLink messaging system\n4. Submit a concern if you need academic assistance\n\nAlways include your course name and student ID in communications.',NULL,NULL,NULL,NULL,NULL,'academic','general','[\"instructor\", \"contact\", \"email\", \"office hours\"]','2','1','bulk_import','6b98da98-7378-4921-82be-dc009e62c41f','40','2025-09-16 18:55:00','2025-09-16 18:55:00'),
('9','faq','What are the library hours?','Library hours are:\n- Monday-Friday: 8:00 AM - 8:00 PM\n- Saturday: 9:00 AM - 5:00 PM\n- Sunday: Closed\n\nExtended hours may be available during exam periods. Check the library website or StudentLink announcements for updates.',NULL,NULL,NULL,NULL,NULL,'services','general','[\"library\", \"hours\", \"schedule\", \"access\"]','1','1','bulk_import','6b98da98-7378-4921-82be-dc009e62c41f','40','2025-09-16 18:55:00','2025-09-16 18:55:00'),
('10','faq','What is Bestlink College of the Philippines?','Bestlink College of the Philippines (BCP) is a non-stock, non-profit, and non-sectarian educational institution founded in June 2002 by Dr. Maria M. Vicente and Engr. Reynaldo Corpuz. It started as an institute offering TESDA-accredited computer courses and later expanded into a full college with CHED-approved 4-year degree programs.',NULL,NULL,NULL,NULL,NULL,'general','student_support','[\"bcp\", \"college\", \"history\", \"founding\"]','3','1','bcp_training_upload','16cef2e4-d6f2-41f5-9907-090e806f950a','40','2025-10-08 16:31:43','2025-10-08 16:31:43'),
('11','faq','What kinds of programs does BCP offer?','BCP offers a variety of programs including undergraduate degrees such as Information Technology (BSIT), Business Administration (BSBA), Hotel & Restaurant Management (BSHRM), Criminology, Psychology, Education, Computer Engineering, Office Administration, and more. It also provides technical-vocational and TESDA-accredited courses, as well as Senior High School tracks in Academic, Technical-Vocational, and Arts & Design strands.',NULL,NULL,NULL,NULL,NULL,'academic','student_support','[\"programs\", \"degrees\", \"courses\", \"senior high school\"]','3','1','bcp_training_upload','16cef2e4-d6f2-41f5-9907-090e806f950a','40','2025-10-08 16:31:43','2025-10-08 16:31:43'),
('12','faq','How much is the tuition at BCP?','Students at Bestlink College of the Philippines do not pay tuition; they only pay a fixed amount for miscellaneous fees per semester (approximately PHP 4,975) thanks to scholarships through the EJA Vicente Foundation and other support mechanisms.',NULL,NULL,NULL,NULL,NULL,'financial','student_support','[\"tuition\", \"fees\", \"scholarship\", \"cost\"]','3','1','bcp_training_upload','16cef2e4-d6f2-41f5-9907-090e806f950a','40','2025-10-08 16:31:43','2025-10-08 16:31:43'),
('13','faq','Where are the campuses of Bestlink located?','The main campus is located along Quirino Highway, Barangay Kaligayahan, Novaliches, Quezon City. There are also branch campuses in Bulacan and additional sites such as San Agustin, Novaliches.',NULL,NULL,NULL,NULL,NULL,'general','student_support','[\"location\", \"campus\", \"address\", \"branches\"]','2','1','bcp_training_upload','16cef2e4-d6f2-41f5-9907-090e806f950a','40','2025-10-08 16:31:43','2025-10-08 16:31:43'),
('14','faq','What Senior High School tracks does BCP offer?','Senior High School at BCP offers Academic Tracks including STEM, ABM (Accountancy & Business Management), HUMSS, and GAS; Technical-Vocational Tracks such as Information & Communication Technology (ICT) and Home Economics; and an Arts & Design Track in Performing Arts.',NULL,NULL,NULL,NULL,NULL,'academic','student_support','[\"senior high school\", \"tracks\", \"stem\", \"abm\", \"humss\", \"gas\"]','3','1','bcp_training_upload','16cef2e4-d6f2-41f5-9907-090e806f950a','40','2025-10-08 16:31:43','2025-10-08 16:31:43'),
('15','faq','What is the history behind Bestlink\'s name and founding?','The institution began in June 2002 as \'LOG-ON TODAY\' and soon changed its name to Bestlink Institute of Information Technology (BIIT), inspired by the motto \'Be trained to be the best; be linked to success.\' In 2012, with the addition of CHED-accredited 4-year degree programs, it was renamed Bestlink College of the Philippines.',NULL,NULL,NULL,NULL,NULL,'general','student_support','[\"history\", \"founding\", \"name\", \"motto\"]','2','1','bcp_training_upload','16cef2e4-d6f2-41f5-9907-090e806f950a','40','2025-10-08 16:31:43','2025-10-08 16:31:43'),
('16','faq','How many students are enrolled at BCP?','As of the first semester of Academic Year 2023-2024, Bestlink College of the Philippines had approximately 45,148 students enrolled.',NULL,NULL,NULL,NULL,NULL,'general','student_support','[\"enrollment\", \"students\", \"population\", \"statistics\"]','2','1','bcp_training_upload','16cef2e4-d6f2-41f5-9907-090e806f950a','40','2025-10-08 16:31:43','2025-10-08 16:31:43'),
('17','faq','What are the admission requirements for Senior High School at BCP?','Admission requirements for Senior High School include the original Junior High School Card (Form 138), Certificate of Good Moral Character, a colored copy of the PSA Birth Certificate, and two 2x2 photos with a white background. Specific strand requirements may vary.',NULL,NULL,NULL,NULL,NULL,'academic','student_support','[\"admission\", \"requirements\", \"senior high school\", \"documents\"]','3','1','bcp_training_upload','16cef2e4-d6f2-41f5-9907-090e806f950a','40','2025-10-08 16:31:43','2025-10-08 16:31:43'),
('18','faq','Does BCP have modern facilities?','Yes, Bestlink College of the Philippines has newly constructed and improved facilities designed to support its growing student population and academic programs.',NULL,NULL,NULL,NULL,NULL,'general','student_support','[\"facilities\", \"infrastructure\", \"modern\", \"campus\"]','2','1','bcp_training_upload','16cef2e4-d6f2-41f5-9907-090e806f950a','40','2025-10-08 16:31:43','2025-10-08 16:31:43'),
('19','faq','What is the mission or vision of BCP?','Bestlink College of the Philippines is committed to providing quality education with a modern, research-based curriculum and delivery systems aimed at excellence. Their motto is \'Be trained to be the best; be linked to success.\'',NULL,NULL,NULL,NULL,NULL,'general','student_support','[\"mission\", \"vision\", \"motto\", \"excellence\"]','2','1','bcp_training_upload','16cef2e4-d6f2-41f5-9907-090e806f950a','40','2025-10-08 16:31:43','2025-10-08 16:31:43'),
('20','faq','How does the scholarship system at BCP work?','BCP students are generally scholars under the EJA Vicente Foundation, which offsets tuition fees so students only pay miscellaneous fees. Senior High School students also benefit from DepEd vouchers and support such as free uniforms, books, and medical exams.',NULL,NULL,NULL,NULL,NULL,'financial','student_support','[\"scholarship\", \"foundation\", \"deped\", \"support\", \"benefits\"]','3','1','bcp_training_upload','16cef2e4-d6f2-41f5-9907-090e806f950a','40','2025-10-08 16:31:43','2025-10-08 16:31:43');
